// Embed only the DSH entry point. References remain packaged files read on demand.
import { writeFileSync } from "node:fs";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { DSH_BROWSER_TOOLS, validateSkillDirectory } from "./validate-skill.mjs";

const pkg = join(dirname(fileURLToPath(import.meta.url)), "..");
const { name, description, content } = validateSkillDirectory(join(pkg, "skill"), {
  maxEntryBytes: 4_500,
  browserTools: DSH_BROWSER_TOOLS,
});
const banner =
  "// GENERATED by scripts/build-skill-content.mjs — do not edit.\n" +
  "// Source: skill/SKILL.md; references are loaded separately from resourceBase.\n";
writeFileSync(
  join(pkg, "src", "skill-content.generated.ts"),
  `${banner}export const BSK_SKILL_NAME = ${JSON.stringify(name)};\n` +
    `export const BSK_SKILL_DESCRIPTION = ${JSON.stringify(description)};\n` +
    `export const BSK_SKILL_MARKDOWN = ${JSON.stringify(content)};\n`,
);
console.log(`skill-content.generated.ts written (${content.length} chars; references deferred)`);
